    // ASM UFO.asm loc_34EEC: targeted shooting starts the shared UFO beam
    // sequence, freezes the UFO, and reloads the one-second loop counter to $32.
    UfoBeamStartLoc34Eec {
        beam_segments: 4,
        beam_interval: 5,
        x_velocity: 0,
        y_velocity: 0,
        wait_timer: 0x32,
    }
