fn hand_jump_units_from_random_loc_328aa(
    speed_seed: i16,
    random_byte: u8,
    kid_position_word: u16,
) -> i16 {
    let random_component = i16::from((random_byte ^ kid_position_word.to_le_bytes()[0]) & 3);
    speed_seed.wrapping_add(random_component)
}

